package com.acaivis.controller; import com.acaivis.dto.*; import com.acaivis.service.DeliveryZoneService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/delivery-zones") public class DeliveryZoneController {private final DeliveryZoneService s;public DeliveryZoneController(DeliveryZoneService s){this.s=s;} @GetMapping public List<DeliveryZoneResponse> all(){return s.findAll();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public DeliveryZoneResponse create(@Valid @RequestBody DeliveryZoneRequest d){return s.create(d);} @PutMapping("/{id}") public DeliveryZoneResponse update(@PathVariable Long id,@Valid @RequestBody DeliveryZoneRequest d){return s.update(id,d);} @PatchMapping("/{id}/reactivate") public DeliveryZoneResponse reactivate(@PathVariable Long id){return s.reactivate(id);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.delete(id);}}
